# ATLAS, compared against direct LPM at every possible forwarding event.
for trial in range(200):
 routes={}
 for _ in range(rng.randrange(150)):
  length=rng.choice([0,1,2,3,7,32,63,64,65,96,120,127,128,rng.randrange(129)])
  size=1<<(128-length)
  x=rng.getrandbits(128)//size*size
