WIDTH=[16,8,4];LANES=[4,8,16]
def reference(starts, queries, hit, miss, dec, B):
 n=len(starts)
 @functools.lru_cache(None)
 def trees(i,j):
  # Explicitly enumerate all ordered partitions, then form their Cartesian
  # product of best subtree/caching alternatives via budget convolution.
  q=sum(repeat*sum(i<=r<j for r in rs) for repeat,rs in queries)
  t=sum(repeat*any(i<=r<j for r in rs) for repeat,rs in queries)
  best={}
  for mask in range(1<<(j-i-1)):
   cuts=[i]+[k for k in range(i+1,j) if mask>>(k-i-1)&1]+[j]
   b=len(cuts)-1
   if b==1:
    if j-i>8:continue
    b=0
    sub={0:(0,0)}
   else:
    if b>9:continue
    sub={0:(0,0)}
    for lo,hi in zip(cuts,cuts[1:]):
     nxt={}
     for a,aa in sub.items():
      for c,cc in trees(lo,hi).items():
       if a+c>B:continue
       cost=aa[0]+cc[0],aa[1]+cc[1]
       if a+c not in nxt or cost<nxt[a+c]:nxt[a+c]=cost
     sub=nxt
   k=b-1 if b else j-i
   for mode in range(3):
    if mode and starts[j-1]-starts[i]>=(1<<(64 if mode==1 else 32)):continue
    P=(32+4*b+k*WIDTH[mode]+63)//64
    for cached in range(2):
     use=cached*P
     w=P*(hit if cached else miss)*t+((k+LANES[mode]-1)//LANES[mode]+dec[mode])*q
     for s,ss in sub.items():
      if s+use>B:continue
      cost=w+ss[0],P+ss[1]
      if s+use not in best or cost<best[s+use]:best[s+use]=cost
  return best
 return trees(0,n)

for trial in range(100):
 B=rng.randrange(7); hit=rng.randrange(1,4);miss=rng.randrange(hit,12);dec=[rng.randrange(5) for _ in range(3)]
 versions=[];bursts=[];qs=[]
 for v in range(rng.randrange(1,4)):
