  versions.append((starts,list(range(n))))
  queries=[]
  for _ in range(rng.randrange(8)):
   rs=[rng.randrange(n) for _ in range(rng.randrange(9))];repeat=rng.randrange(1,5)
   queries.append((repeat,rs));bursts.append((v,repeat,[starts[r] for r in rs]))
  qs.append(queries)
 expected={0:(0,0)}
 for (starts,_),queries in zip(versions,qs):
  ref=reference(starts,queries,hit,miss,dec,B)
  nxt={}
  for a,aa in expected.items():
   for c,cc in ref.items():
    if a+c>B:continue
    cost=aa[0]+cc[0],aa[1]+cc[1]
    if a+c not in nxt or cost<nxt[a+c]:nxt[a+c]=cost
  expected=nxt
 best=min(expected.values());best=(best[0],best[1]+sum(1+(4*len(s)+63)//64 for s,h in versions))
 objective,images,answers=native.optimize(versions,bursts,B,(hit,miss,dec))
 assert tuple(objective)==best,(trial,best,objective,versions,bursts,B,hit,miss,dec)
 # Validate image bytes, budgets and the entire reported cost independently.
 resident=pages=work=0; nodes=[]
 for image,(starts,hops) in zip(images,versions):
  ns,ps=decode_image(image,starts,hops);nodes.append(ns);pages+=ps
  resident+=sum(n['pages'] for n in ns.values() if n['cached'])
 for (v,repeat,addrs),rows in zip(bursts,answers):
  visits={}
  for x,row in zip(addrs,rows):
   rank=bisect.bisect_right(versions[v][0],x)-1
   assert row[0:2]==[versions[v][1][rank],rank]
   off=64;path=[]
   while 1:
    path.append(off);visits[off]=visits.get(off,0)+1;n=nodes[v][off]
    if n['kind']:break
    off=n['children'][bisect.bisect_right(n['keys'],x)]
   assert row[2]==path
  for off,q in visits.items():
   nd=nodes[v][off];k=len(nd['keys']);mode=nd['mode']
   work+=repeat*(nd['pages']*(hit if nd['cached'] else miss)+((k+LANES[mode]-1)//LANES[mode]+dec[mode])*q)
 assert resident<=B
 assert objective==[work,pages]
