for trial in range(100):
 n=rng.randrange(1,65)
 scale=rng.choice([1,1<<24,1<<32,1<<63,1<<64,1<<120])
 starts=[0]+sorted(rng.sample(range(1,120),n-1));starts=[x*scale for x in starts]
 hops=[rng.choice([0,None,1,2147483647]) for _ in starts]
 # ensure canonical values
