   cuts=[i]+sorted(rng.sample(range(i+1,j),rng.randrange(1,min(9,j-i))))+[j]
   nd['children']=[node(a,b) for a,b in zip(cuts,cuts[1:])]
  return nd
 tree=node(0,n)
 addresses=sorted({0,(1<<128)-1,*starts,*[max(0,x-1) for x in starts],*[rng.getrandbits(128) for _ in range(50)]})
 image,answers=native.pack(starts,hops,tree,addresses)
